/**
 * The card's assets, embedded.
 *
 * Not read from disk and not fetched: `new URL('./font.ttf', import.meta.url)`
 * is rewritten by the bundler into a relative asset path, which `fetch` cannot
 * resolve while a page is being prerendered, and a file path is not reliably
 * traced into a serverless function either. A card that throws produces no
 * preview at all, which is worse than a plain one - so the bytes travel with
 * the code.
 *
 * Sora and Manrope are both SIL OFL, so redistributing them is fine. Only the
 * two weights the card actually draws are here; a full family would make every
 * render slower for nothing.
 *
 * Regenerate with: base64 the file, paste. See lib/og/*.ttf for the sources.
 */

const decode = (s: string): ArrayBuffer => {
  const bin = Buffer.from(s, 'base64');
  return bin.buffer.slice(bin.byteOffset, bin.byteOffset + bin.byteLength) as ArrayBuffer;
};

const SORA_BOLD_B64 = '';

const MANROPE_MEDIUM_B64 = '';

const CREST_B64 = '';

export const soraBold = () => decode(SORA_BOLD_B64);
export const manropeMedium = () => decode(MANROPE_MEDIUM_B64);
export const crestDataUrl = `data:image/png;base64,${CREST_B64}`;
